-- -----------------------------
-- Table structure for `angkatans`
-- -----------------------------
DROP TABLE IF EXISTS `angkatans`;
CREATE TABLE `angkatans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pelatihan_id` bigint unsigned NOT NULL,
  `nomor_angkatan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal_mulai` date NOT NULL,
  `tanggal_selesai` date NOT NULL,
  `jumlah_peserta` int unsigned NOT NULL DEFAULT '0',
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Direncanakan','Berjalan','Selesai','Dibatalkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Direncanakan',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `angkatans_pelatihan_id_foreign` (`pelatihan_id`),
  CONSTRAINT `angkatans_pelatihan_id_foreign` FOREIGN KEY (`pelatihan_id`) REFERENCES `pelatihans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1226 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

